package com.example.domain.model.i18n

internal object DuaJa1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("目覚めのドゥアー", "死（眠り）の後に私たちを生かしてくださったアッラーに、あらゆる称賛あれ。帰り着く先はアッラーのもとである。", "眠りから目覚めた直後、アッラーに感謝するために唱える。", "預言者ムハンマド（彼に平安あれ）は目覚めた時にこれを唱えられた——感謝と来世への想いで一日を始める。"),
        "dua_leaving_home" to DuaText("家を出る時のドゥアー", "アッラーの御名において。私はアッラーにのみ信頼する。力も権能もアッラーによらねば存在しない。", "家を出る一歩を踏み出す時、アッラーの守護を求めて。", "天使たちは言う：「あなたは導かれ、満たされ、守られた」。悪魔は遠ざかる。"),
        "dua_anxiety_distress" to DuaText("不安と悲しみからの解放", "おおアッラーよ、不安と悲しみから、無力さと怠惰から、けち根性と臆病から、借金の重荷と人に支配されることから、あなたに御加護を求めます。", "悲しみ、不安、借金、精神的苦悩の時に。", "預言者（彼に平安あれ）はこれをよく唱えられた——悲しみ、怠惰、借金の不安からの御加護。"),
        "dua_sayyidul_istighfar" to DuaText("悔悟の言葉の長（サイイド・イスティグファール）", "おおアッラーよ、あなたは私の主。あなたの他に崇拝すべきものはありません。あなたは私を創造され、私はあなたの僕です。私はできる限りあなたとの契約と約束を守ります。私が行った悪事の害からあなたに御加護を求めます。あなたが私に与えられた恵みを認め、また私の罪を認めます。どうか私をお赦しください、あなたの他に罪を赦す者はいないのですから。", "朝と夕に——預言者（彼に平安あれ）が教えられた最も優れた悔悟の言葉。", "確信を持って夕方に唱えその夜に死んだ者は楽園に入る。朝に唱えても同様である。"),
        "dua_parents" to DuaText("両親のためのドゥアー", "わが主よ、彼らが幼い私を育ててくれたように、彼らに御慈悲をお与えください。", "幼少期の養育への恩返しとして両親のために唱えるクルアーンのドゥアー。", "アッラー御自身がこの両親のためのドゥアーを命じられた。"),
        "dua_entering_mosque" to DuaText("モスクに入る時のドゥアー", "おおアッラーよ、あなたの御慈悲の扉を私に開いてください。", "右足からモスクに入る時に唱える。", "預言者（彼に平安あれ）はモスクに入る時にこのドゥアーを教えられた。"),
        "dua_morning_asbahna" to DuaText("朝の唱念", "私たちは朝を迎え、すべての支配権はアッラーのものとして朝を迎えました。あらゆる称賛はアッラーに。アッラーの他に崇拝すべきものはなく、御一人であり、同位者はいません。支配権も称賛も御方のもの、御方はすべての事に全能です。", "朝に唱えるスンナのドゥアー。", "アッラーの主権と唯一性を認めることから一日が始まる。"),
        "dua_evening_amsayna" to DuaText("夕の唱念", "私たちは夕べを迎え、すべての支配権はアッラーのものとして夕べを迎えました。あらゆる称賛はアッラーに。アッラーの他に崇拝すべきものはなく、御一人であり、同位者はいません。支配権も称賛も御方のもの、御方はすべての事に全能です。", "夕方に唱えるスンナのドゥアー。", "アッラーの主権と唯一性を認めることから夜が始まる。"),
        "dua_bismillah_la_yadurru" to DuaText("あらゆる害からの守護", "アッラーの御名において。その御名により天にも地にも害を及ぼすものはなく、御方は全聴にして全知であられる。", "朝夕それぞれ三回。", "朝夕に三回唱える者には、いかなるものも害を及ぼさない。"),
        "dua_raditu_billahi" to DuaText("アッラーを主として満足する", "私はアッラーを主として、イスラームを宗教として、ムハンマド（彼に平安あれ）を預言者として満足しました。", "朝夕それぞれ三回。", "審判の日に彼を満足させることがアッラーの権利となる。"),
        "dua_hasbiyallah" to DuaText("ハスビヤッラー（アッラーで十分）", "アッラーは私に十分であられる。御方の他に神はいない。私は御方に信頼し、御方は偉大な玉座の主であられる。", "朝夕それぞれ七回。", "クルアーンの一節。アッラーは現世と来世の心配事に対して十分であられる。"),
        "dua_subhanallah_wa_bihamdihi" to DuaText("スブハーナッラーヒ・ワ・ビハムディヒ", "アッラーに栄光あれ、あらゆる称賛は御方のもの。", "一日百回。", "一日百回唱える者は、たとえ海の泡ほど罪があっても赦される。"),
        "dua_tahleel_100" to DuaText("ラー・イラーハ・イッラッラー（百回）", "アッラーの他に崇拝すべきものはなく、御一人であり、同位者はいません。支配権も称賛も御方のもの、御方はすべての事に全能です。", "一日百回唱えることに大きな功徳がある。", "奴隷十人を解放した報奨に等しく、百の善行が記され、百の罪が消され、夕方まで悪魔から守られる。"),
        "dua_leaving_mosque" to DuaText("モスクを出る時のドゥアー", "おおアッラーよ、あなたの恩恵を求めます。", "左足からモスクを出る時に唱える。", "モスクを出る時にアッラーの恩恵と糧を求める。"),
        "dua_after_adhan" to DuaText("アザーンの後のドゥアー", "おおアッラーよ、この完全な呼びかけと、まもなく行われる礼拝の主よ、ムハンマド（彼に平安あれ）にワシーラと徳をお与えください。そしてあなたが約束された称賛される地位に彼を昇らせてください。", "アザーンが終わった後。", "これを唱える者は審判の日に預言者（彼に平安あれ）のとりなしを受ける。"),
        "dua_after_salah_istighfar" to DuaText("義務の礼拝の後", "アッラーに御赦しを求めます（三回）。おおアッラーよ、あなたはサラームであり、平安は御方から来る。祝福あれ、威厳と栄光の主よ。", "サラームの直後。", "預言者（彼に平安あれ）は義務の礼拝の後、毎回これを唱えられた。"),
        "dua_after_salah_help_dhikr" to DuaText("あなたを憶えるための助けを", "おおアッラーよ、あなたを憶え、あなたに感謝し、最善の方法であなたを崇拝できるよう私を助けてください。", "毎回の礼拝の後——預言者（彼に平安あれ）はムアーズ（彼に御満悦あれ）にこう唱えるよう勧められた。", "預言者（彼に平安あれ）の特別な助言——崇拝における卓越と持続。"),
        "dua_ayatul_kursi" to DuaText("礼拝後のアーヤトゥル・クルシー", "アッラー、御方の他に神はなく、永生にして万物の維持者であられる。まどろみも眠りも御方を捉えない。天と地にあるすべては御方のもの。御方の許しなくして誰が御方の御前でとりなしできようか。御方は彼らの前にあることも後にあることも知っておられる。御方が望まれることの他、彼らは御方の知識について何も理解できない。御方の玉座は天と地に及び、それらを守ることは御方を疲れさせない。御方は至高にして偉大であられる。", "義務の礼拝の後、そして眠る前に。", "義務の礼拝の後に唱える者と楽園の間には死のみが立ちはだかる。眠る前に唱えれば朝まで守られる。"),
        "dua_before_sleep" to DuaText("就寝前のドゥアー", "おおアッラーよ、あなたの御名において私は死に（眠り）、生きます（目覚めます）。", "床についた後。", "預言者（彼に平安あれ）は眠る前にこれを唱えられた。"),
        "dua_sleep_tasbeeh" to DuaText("就寝前のファーティマのタスビーフ", "アッラーに栄光あれ（33回）、あらゆる称賛はアッラーに（33回）、アッラーは至大であられる（34回）。", "就寝前——預言者（彼に平安あれ）はファーティマとアリー（彼らに御満悦あれ）に教えられた。", "預言者（彼に平安あれ）はこれが召使いより良いと仰せになった。"),
        "dua_sleep_qina_adhab" to DuaText("懲罰からの守護", "おおアッラーよ、あなたが僕たちを復活させる日、あなたの懲罰から私を守ってください。", "右手を頬の下に置いて三回。", "眠りを死の想起と来世への準備に変える。"),
        "dua_bad_dream" to DuaText("悪夢を見た後", "呪われた悪魔からアッラーに御加護を求めます。", "悪夢の後：左側に軽く三回唾を吐く仕草をし、体の向きを変える。", "悪夢はあなたに害を及ぼさない。誰にも話してはいけない。"),
        "dua_yunus" to DuaText("ユーヌス預言者（彼に平安あれ）のドゥアー", "あなたの他に神はいません。あなたに栄光あれ。まことに私は不正な者たちの一人でした。", "鯨の腹の中でのユーヌス預言者のドゥアー——あらゆる苦難に対して。", "どんなことについてもこれを唱えるムスリムに、アッラーは応えられる。"),
        "dua_karb" to DuaText("深刻な苦難の時のドゥアー", "アッラーの他に神はいません。御方は偉大にして寛大であられる。アッラーの他に神はいません。御方は偉大な玉座の主であられる。アッラーの他に神はいません。御方は天の主、地の主、尊い玉座の主であられる。", "深刻な苦難と困難の時に。", "預言者（彼に平安あれ）は苦難の時にこれを唱えられた。"),
        "dua_ya_hayyu_ya_qayyum" to DuaText("おお永生にして維持者よ", "おお永生にして万物の維持者よ、あなたの御慈悲によって助けを求めます。", "事態が非常に重くなった時に。", "何かが預言者（彼に平安あれ）を苦しめる度、御方はこう唱えられた。"),
        "dua_hasbunallah" to DuaText("アッラーは私たちに十分、最良の管理者", "アッラーは私たちに十分であり、御方は最良の管理者であられる。", "敵を恐れる時や大きな危険に直面した時に。", "イブラーヒーム預言者（彼に平安あれ）は火に投げ込まれた時にこれを唱え、預言者（彼に平安あれ）も危険の時にこれを唱えられた。"),
        "dua_entering_home" to DuaText("家に入る時のドゥアー", "アッラーの御名において。", "家に入る時にアッラーの御名を唱え、サラームで挨拶する。", "家に入る時と食事の時にアッラーが憶えられれば、悪魔は言う：ここには泊まる場所も夕食もない、と。"),
        "dua_travel" to DuaText("旅（乗り物）のドゥアー", "これを私たちに従わせてくださった御方に栄光あれ。私たちは自分たちでこれを制することはできなかった。まことに私たちはわが主のもとに帰ります。", "乗り物に乗ってアッラーフ・アクバルを三回唱えた後。", "守護と祝福のためのスンナの旅のドゥアー。"),
        "dua_entering_market" to DuaText("市場に入る時のドゥアー", "アッラーの他に崇拝すべきものはなく、御一人であり、同位者はいません。支配権も称賛も御方のもの。御方は生かし、死なせ、永生にして決して死なれない。あらゆる善は御方の御手にあり、御方はすべての事に全能です。", "市場に入る時に。", "ハディースにはこれに対する大きな報奨（百万の善行）が述べられている。"),
        "dua_adam_forgiveness" to DuaText("アーダム預言者（彼に平安あれ）のドゥアー", "わが主よ、私たちは自らに不正を行いました。もしあなたが私たちをお赦しにならず御慈悲をお与えにならなければ、私たちは必ず失う者となるでしょう。", "アーダムとハウワー（彼らに平安あれ）の悔悟のドゥアー。", "人類最初の悔悟——アッラーはそれを受け入れられた。"),
        "dua_abu_bakr" to DuaText("アブー・バクル（彼に御満悦あれ）に教えられたドゥアー", "おおアッラーよ、私は自らに大いに不正を行いました。あなたの他に罪を赦す者はいません。どうか御自ら私をお赦しになり御慈悲をお与えください。まことにあなたは赦す御方、慈悲深い御方です。", "預言者（彼に平安あれ）はアブー・バクル・スィッディーク（彼に御満悦あれ）に礼拝の中で（タシャッフドの後に）唱えるよう教えられた。", "礼拝の終わりに唱えるスンナのドゥアー。"),
        "dua_astaghfirullah_atubu" to DuaText("日々のイスティグファール", "アッラーに御赦しを求め、御方に悔悟して立ち返ります。", "預言者（彼に平安あれ）は一日に七十回以上御赦しを求められた。", "預言者（彼に平安あれ）は仰せになった：私は一日に七十回以上アッラーに御赦しを求め悔悟する。"),
        "dua_laylatul_qadr" to DuaText("ライラトゥル・カドルのドゥアー", "おおアッラーよ、あなたは大いに赦す御方であり、赦すことを愛されます。どうか私をお赦しください。", "アーイシャ（彼女に御満悦あれ）にライラトゥル・カドルのために教えられた。", "ラマダーンの最後の夜とライラトゥル・カドルのための特別なドゥアー。"),
        "dua_family_coolness" to DuaText("目の涼しさ（配偶者と子供）", "わが主よ、私たちの配偶者と子孫から私たちの目の涼しさをお与えください。そして私たちを敬虔な者たちの模範としてください。", "善良な配偶者と子供を求めるクルアーンのドゥアー。", "家庭の平安と善良な子供のために。"),
        "dua_righteous_children" to DuaText("正しい子孫のために", "わが主よ、あなた御自身から清らかな子孫を私にお与えください。まことにあなたは祈願を聞き届けられる御方です。", "ザカリーヤ預言者（彼に平安あれ）のドゥアー。", "子供を求める者のためのクルアーンのドゥアー。"),
        "dua_ibrahim_prayer_family" to DuaText("礼拝を確立する者", "わが主よ、私と私の子孫を礼拝を確立する者としてください。わが主よ、私の祈願をお受け入れください。わが主よ、清算が行われる日に私と私の両親と信者たちをお赦しください。", "イブラーヒーム預言者（彼に平安あれ）が自身と子孫のために唱えたドゥアー。", "一般に礼拝の終わりに唱えられる。"),
        "dua_newlywed" to DuaText("新婚夫婦への祝福", "アッラーがあなたを祝福されますように。あなたに祝福を降し、あなたがた二人を善の中で結びつけられますように。", "誰かの結婚を祝福する時に。", "結婚に対するスンナの祝福の言葉。"),
        "dua_before_eating" to DuaText("食事前のドゥアー", "アッラーの御名において。（忘れた場合：）アッラーの御名において、その始めから終わりまで。", "食事前に唱える。忘れた場合は途中で唱える。", "ビスミッラーを唱えることで悪魔は食物に加わることができなくなる。"),
        "dua_after_eating" to DuaText("食後のドゥアー", "私の力も能力もなしにこれを食べさせ、私に与えてくださったアッラーに、あらゆる称賛あれ。", "食事を終えた後。", "これを唱える者の過去の罪は赦される。"),
        "dua_host" to DuaText("もてなす人のために", "おおアッラーよ、あなたが彼らに与えられたものを祝福し、彼らをお赦しになり御慈悲をお与えください。", "誰かの家で食事をした後、もてなした人のために。", "スンナの方法でもてなしに感謝する。"),
        "dua_breaking_fast" to DuaText("断食を終える時", "喉の渇きは去り、血管は潤い、アッラーが望まれるなら報奨は確定しました。", "イフタールの時に。", "預言者（彼に平安あれ）は断食を終える時にこう仰せになった。"),
        "dua_new_clothes" to DuaText("新しい服を着る時", "おおアッラーよ、あらゆる称賛はあなたのもの、あなたが私にこれを着せてくださいました。私はその良さと、それが作られた目的の良さをあなたに求め、その悪さと、それが作られた目的の悪さからあなたに御加護を求めます。", "新しい服（シャツやターバンなど、その名前を挙げて）を着る時に。", "預言者（彼に平安あれ）は新しい服を着る時にこのドゥアーをされた。（毎日の着衣のドゥアーは「服を着る」の項にある。）"),
        "dua_rabbana_atina" to DuaText("現世と来世の善", "わが主よ、現世で私たちに善をお与えください。来世でも善をお与えください。そして業火の懲罰から私たちをお守りください。", "預言者（彼に平安あれ）が最も頻繁に唱えられたドゥアー。", "現世と来世のあらゆる善を集めるドゥアー。"),
        "dua_rabbi_zidni_ilma" to DuaText("知識の増加", "わが主よ、私の知識を増してください。", "知識の増加のために。", "アッラーは預言者（彼に平安あれ）に知識の増加以外何も求めるなと命じられた。"),
        "dua_musa_sharh_sadr" to DuaText("胸を開くドゥアー（ムーサー）", "わが主よ、私の胸を広げ、私の仕事を容易にし、私の舌の結び目を解いてください。彼らが私の言葉を理解できるように。", "試験、スピーチ、あるいは困難な仕事の前に。", "ムーサー預言者（彼に平安あれ）のドゥアー——心の平静と仕事の容易さ。"),
        "dua_la_tuzigh" to DuaText("心の堅固さ", "わが主よ、あなたが私たちを導かれた後、私たちの心を逸らさないでください。そしてあなた御自身から御慈悲をお与えください。まことにあなたは大いに与える御方です。", "導きの上に堅固でいるために。", "信仰に堅く留まるためのドゥアー。"),
        "dua_ya_muqallib" to DuaText("おお心を転じる御方よ", "おお心を転じる御方よ、私の心をあなたの宗教の上に堅固にしてください。", "預言者（彼に平安あれ）はよくこのドゥアーをされた。", "ウンム・サラマ（彼女に御満悦あれ）によれば、預言者（彼に平安あれ）が最も頻繁に唱えられたドゥアー。"),
        "dua_la_tuakhidhna" to DuaText("バカラ章の最後の二節", "わが主よ、もし私たちが忘れたり間違えたりしても、私たちを罰しないでください。わが主よ、私たちより前の者たちに課されたような重荷を私たちに課さないでください。わが主よ、私たちが耐えられないものを私たちに負わせないでください。私たちを許し、赦し、御慈悲をお与えください。あなたは私たちの守護者です。不信仰の民に対して私たちをお助けください。", "夜、眠る前に——バカラ章の最後の二節。", "夜にバカラ章の最後の二節を唱える者には、それで十分である。"),
        "dua_visiting_sick" to DuaText("病人を見舞う時", "偉大な玉座の主である偉大なアッラーに、あなたを治してくださるよう求めます。", "病人を見舞う時に七回。", "死の時が来ていなければ、アッラーは彼を治される。"),
        "dua_ruqyah_pain" to DuaText("体の痛みのために", "私が感じ恐れる悪から、アッラーとその御力に御加護を求めます。", "痛む場所に手を置き、ビスミッラーを三回唱え、その後このドゥアーを七回唱える。", "預言者（彼に平安あれ）はウスマーン・イブン・アビル＝アース（彼に御満悦あれ）に痛みのためにこれを教えられた。"),
        "dua_ruqyah_nabawi" to DuaText("病人のための預言者のルクヤ", "おおアッラーよ、人類の主よ、害を取り除き治癒をお与えください。あなたこそ治す御方、あなたの治癒の他に治癒はありません。病を残さない治癒をお与えください。", "病人に手を当てながら。", "預言者（彼に平安あれ）は家族の病人を見舞う時にこれを唱えられた。"),
        "dua_kalimat_tammat" to DuaText("完全な御言葉への御加護", "アッラーの創造されたものの悪から、アッラーの完全な御言葉に御加護を求めます。", "ある場所に滞在する時、または夕方に。", "ある場所に滞在してこれを唱える者には、そこを去るまで何も害を及ぼさない。"),
        "dua_evil_eye" to DuaText("子供の守護（邪視から）", "すべての悪魔、すべての毒あるもの、あらゆる害をなす目から、アッラーの完全な御言葉によってあなたがた二人の守護を求めます。", "預言者（彼に平安あれ）はハサンとフサイン（彼らに御満悦あれ）にこれを唱えられた。", "子供を邪視と害から守るスンナのドゥアー（一人の子供には「ウイーズカ」と言う）。"),
        "dua_seeing_afflicted" to DuaText("試練にある人を見た時", "御方があなたを試されたことから私を免れさせ、御方の創造物の多くより私を優遇してくださったアッラーに、あらゆる称賛あれ。", "誰かが試練にある時（心の中で静かに唱える）。", "これを唱える者はその試練から守られる。"),
        "dua_istikhara" to DuaText("イスティハーラの礼拝", "おおアッラーよ、あなたの御知識によって善を求め、あなたの御力によって能力を求め、あなたの偉大な恩恵を求めます。あなたは力をお持ちで私にはなく、あなたは御存知で私は知りません。あなたは幽玄の知者であられます。おおアッラーよ、もしこの事（心に思い浮かべること）が私の宗教、生活、そして結末にとって良いことをあなたが御存知なら、それを私に定め、容易にし、祝福してください。もしこの事が私の宗教、生活、結末にとって悪いことをあなたが御存知なら、それを私から遠ざけ、私をそれから遠ざけてください。そしてどこにあろうと善を私に定め、それに満足させてください。", "合法な事柄における最善を求めて、二ラクアの自発的な礼拝の後に。", "預言者（彼に平安あれ）は教友たちに、クルアーンの章を教えるようにあらゆる事柄でイスティハーラを教えられた。"),
        "dua_allahumma_bika_asbahna" to DuaText("アッラーフンマ・ビカ・アスバフナー", "おおアッラーよ、あなたによって私たちは朝を迎え、あなたによって夕べを迎えます。あなたによって生き、あなたによって死に、復活はあなたのもとへです。", "朝に。", "預言者（彼に平安あれ）は教友たちに朝夕これを唱えるよう教えられた。"),
        "dua_allahumma_bika_amsayna" to DuaText("アッラーフンマ・ビカ・アムサイナー", "おおアッラーよ、あなたによって私たちは夕べを迎え、あなたによって朝を迎えます。あなたによって生き、あなたによって死に、帰り着く先はあなたのもとです。", "夕方に。", "預言者（彼に平安あれ）は教友たちに朝夕これを唱えるよう教えられた。"),
        "dua_afiyah_morning" to DuaText("アーフィヤ（健やかさ）を求める", "おおアッラーよ、現世と来世における赦しと健やかさをあなたに求めます。", "預言者（彼に平安あれ）は朝も夕もこのドゥアーを欠かされなかった。", "健やかさより良いものは誰にも与えられていない。"),
        "dua_afini_fi_badani" to DuaText("体・聴覚・視覚の健康", "おおアッラーよ、私の体に健康をお与えください。おおアッラーよ、私の聴覚に健康をお与えください。おおアッラーよ、私の視覚に健康をお与えください。あなたの他に神はいません。", "朝夕それぞれ三回。", "健康と感覚の守護のためのドゥアー。"),
        "dua_ya_hayyu_aslih" to DuaText("すべての事を正してください", "おお永生にして維持者よ、あなたの御慈悲によって助けを求めます。私のすべての事を正し、瞬き一つの間も私を自分自身に委ねないでください。", "預言者（彼に平安あれ）はファーティマ（彼女に御満悦あれ）に朝夕これを唱えるよう勧められた。", "あらゆる事においてアッラーの助けを求める。"),
        "dua_subhanallah_adada_khalqihi" to DuaText("ジュワイリーヤ（彼女に御満悦あれ）のタスビーフ", "アッラーに栄光あれ、あらゆる称賛は御方のもの——御方の創造物の数ほど、御方が満足される量ほど、御方の玉座の重さと御言葉のインクに等しいほどに。", "朝に三回——何時間もの唱念より重い。", "この四つの言葉を三回唱えることは、夜明けから午前中までの唱念を上回る。"),
        "dua_salawat" to DuaText("イブラーヒーム式のサラワート", "おおアッラーよ、あなたがイブラーヒーム（彼に平安あれ）とその家族に祝福を降されたように、ムハンマド（彼に平安あれ）とその家族に祝福を降してください。あなたは称賛される御方、栄光ある御方です。おおアッラーよ、あなたがイブラーヒーム（彼に平安あれ）とその家族を祝福されたように、ムハンマド（彼に平安あれ）とその家族を祝福してください。あなたは称賛される御方、栄光ある御方です。", "礼拝の中でも常時でも預言者（彼に平安あれ）へのサラワート。", "一度サラワートを送る者に、アッラーは十の慈悲を降される（ムスリム408）。"),
        "dua_wudu_after" to DuaText("ウドゥーの後", "私は証言します、アッラーの他に神はなく、御一人であり、同位者はいないことを。そしてムハンマド（彼に平安あれ）は御方の僕にして使徒であることを。おおアッラーよ、私を悔悟する者、身を清める者の一人としてください。", "ウドゥーを終えた後。", "楽園の八つの扉が開かれ、望む扉から入ることができる。"),
        "dua_wudu_before" to DuaText("ウドゥーの前", "アッラーの御名において。", "ウドゥーを始める時に。", "その上でアッラーの御名を唱えない者に（完全な）ウドゥーはない。"),
        "dua_istiftah" to DuaText("礼拝開始のドゥアー", "おおアッラーよ、あなたに栄光あれ、あなたに称賛あれ。あなたの御名は祝福され、あなたの威厳は高められ、あなたの他に神はいません。", "礼拝の始め、開始のタクビールの直後に。", "礼拝開始のスンナのドゥアー。"),
        "dua_ruku" to DuaText("ルクーウにおいて", "偉大なるわが主に栄光あれ。", "ルクーウで少なくとも三回。", "ルクーウのスンナのタスビーフ。"),
        "dua_sujood" to DuaText("スジュードにおいて", "至高なるわが主に栄光あれ。", "スジュードで少なくとも三回。", "僕がその主に最も近づくのは平伏の時である（ムスリム482）。"),
        "dua_rising_ruku" to DuaText("ルクーウから起き上がる時", "アッラーは御方を称える者に耳を傾けられる。わが主よ、あらゆる称賛はあなたのもの。", "ルクーウから起き上がりまっすぐ立つ時に。", "「ラッバナー・ワ・ラカル＝ハムド」が天使たちのそれと一致する者は、過去の罪が赦される。"),
        "dua_between_sajdas" to DuaText("二つのスジュードの間", "わが主よ、私をお赦しください。わが主よ、私をお赦しください。", "二つの平伏の間に座る時。", "平伏の間の座位のスンナのドゥアー。"),
        "dua_before_salam_four" to DuaText("サラームの前に四つのことから御加護を", "おおアッラーよ、地獄の懲罰から、墓の懲罰から、生と死の試練から、そして偽メシア（ダッジャール）の試練の悪からあなたに御加護を求めます。", "最後のタシャッフドとサラワートの後、サラームの前に。", "預言者（彼に平安あれ）はこの四つのことからの御加護を求めるよう命じられた。"),
        "dua_qunoot_witr" to DuaText("ウィトルのクヌート", "おおアッラーよ、あなたが導かれた人々の中に私を導き、あなたが健やかさを与えられた人々の中に私に健やかさをお与えください。あなたが世話をされた人々の中に私を世話してください。あなたが与えられたものの中で私を祝福し、あなたが定められたものの悪から私を守ってください。あなたは定められ、誰もあなたに逆らって定めることはできません。あなたが友とする者は決して辱められません。祝福され高められたわが主よ、あなたに栄光あれ。", "ウィトルの礼拝で——預言者（彼に平安あれ）はハサン・イブン・アリー（彼に御満悦あれ）に教えられた。", "ウィトルのスンナのクヌート。（ハナフィー派では「アッラーフンマ・インナー・ナスタイーヌカ」もよく知られている。）"),
        "dua_qunoot_hanafi" to DuaText("クヌート（アッラーフンマ・インナー・ナスタイーヌカ）", "おおアッラーよ、私たちはあなたの助けと御赦しを求めます。私たちはあなたを信じ、あなたに頼ります。私たちは最善の方法であなたを称賛し、あなたに感謝し、恩知らずではありません。そしてあなたに背く者を私たちは捨てます。おおアッラーよ、私たちはあなただけを崇拝し、あなたに祈り平伏します。あなたに向かって急ぎ努めます。あなたの御慈悲を望み、あなたの懲罰を恐れます。まことにあなたの懲罰は不信仰者に届くでしょう。", "ウィトルで——ハナフィー派の慣行。", "ウマル（彼に御満悦あれ）から伝えられたクヌート。"),
        "dua_sleep_aslamtu" to DuaText("眠る前の最後の言葉", "おおアッラーよ、私は自らをあなたに委ね、私の事をあなたに任せ、あなたへの希望とあなたへの畏れから私の背をあなたの守護に委ねます。あなたから逃れる場所も避難所もなく、あなたのもとにあるのみです。あなたが下された啓典を信じ、あなたが遣わされた預言者を信じます。", "ウドゥーの後、右側を下にして横たわり——眠る前の最後の言葉。", "その夜に死ねば、フィトラ（イスラーム）の上で死ぬことになる。"),
        "dua_waking_night" to DuaText("夜中に目覚めた時", "アッラーの他に崇拝すべきものはなく、御一人であり、同位者はいません。支配権も称賛も御方のもの、御方はすべての事に全能です。あらゆる称賛はアッラーに、アッラーに栄光あれ、アッラーの他に神はなく、アッラーは至大であり、アッラーによらねば力も権能もありません。おおアッラーよ、私をお赦しください。", "夜中に目覚めた時に。", "彼のドゥアーは応えられ、もしウドゥーをして礼拝すれば、その礼拝は受け入れられる。"),
        "dua_hamm_ibn_masud" to DuaText("苦悩の時のドゥアー（イブン・マスウード）", "おおアッラーよ、私はあなたの僕、あなたの僕の子、あなたの婢女の子です。私の額はあなたの御手の中にあり、あなたの御命令は私に対して行われ、あなたの御裁定は私に対して公正です。あなたが御自身に名付けられ、あるいは御啓典で啓示され、あるいはあなたの創造物の誰かに教えられ、あるいは幽玄の知識のうちに御自身のもとに留められた、あなたに属するすべての御名によってあなたに求めます——クルアーンを私の心の泉とし、私の胸の光とし、私の悲しみの除去とし、私の心配の去来とされますように。", "苦悩と困難の時に——アッラーは悲しみを喜びに変えられる。", "アッラーは彼の心配と悲しみを取り除き、その代わりに喜びをお与えになる。"),
        "dua_difficulty_sahl" to DuaText("何かが困難な時", "おおアッラーよ、あなたが容易にされたもの以外、容易なものはありません。あなたが望めば困難なことも容易にされます。", "何かが困難に感じられる時に。", "試験や困難な仕事における容易さ。"),
        "dua_musibah" to DuaText("災難に遭った時（イスティルジャー）", "私たちはアッラーのものであり、御方のもとに帰ります。おおアッラーよ、私の災難において私に報奨をお与えになり、それに代わるより良いものをお与えください。", "いかなる損失や災難の時にも。", "アッラーは必ずより良いものをお与えになる——ウンム・サラマ（彼女に御満悦あれ）には預言者（彼に平安あれ）がお与えられた。"),
        "dua_debt" to DuaText("借金からの解放のために", "おおアッラーよ、あなたが合法とされたものによって、あなたが禁じられたものから私を十分にし、あなたの恩恵によって、あなた以外のすべてから私を独立させてください。", "借金の返済のために——アリー（彼に御満悦あれ）が教えられた。", "たとえ借金が山のようであっても、アッラーはそれを解決される。"),
        "dua_anger" to DuaText("怒った時", "呪われた悪魔からアッラーに御加護を求めます。", "怒った時に。", "預言者（彼に平安あれ）は、これを唱えれば怒りは去ると仰せになった。"),
        "dua_waswasa" to DuaText("信仰への悪魔の囁きに対して", "私はアッラーと御方の使徒たちを信じます。", "信仰について悪魔的な囁きが来た時に。", "囁きが来たらこれを唱えてそこで止める（そしてアッラーに御加護も求める）。"),
        "dua_travel_full" to DuaText("完全な旅のドゥアー", "おおアッラーよ、この旅において私たちはあなたに正しさと敬虔さを、そしてあなたが満足される行いを求めます。おおアッラーよ、この旅を私たちに容易にし、その距離を短くしてください。おおアッラーよ、あなたは旅の道連れ、家族の守護者です。", "旅に出る時、「スブハーナッラジー・サッハラ」の後に。", "完全なスンナの旅のドゥアー。"),
        "dua_return_travel" to DuaText("旅から帰る時", "私たちは帰ります、悔悟し、崇拝し、わが主を称賛しながら。", "旅から帰る時に。", "預言者（彼に平安あれ）は旅から帰る時にこう仰せになった。"),
        "dua_farewell_traveller" to DuaText("旅立つ人を見送る時", "あなたの宗教、あなたの信託、あなたの行いの結末をアッラーに委ねます。", "旅立つ人を見送る時に。", "アッラーに委ねられたものは決して失われない。"),
        "dua_entering_town" to DuaText("ある場所に滞在する時", "御方が創造されたすべての悪から、アッラーの完全な御言葉に御加護を求めます。", "ある場所に滞在する時、あるいは新しい町に着いた時。", "そこを去るまで何も彼に害を及ぼさない。"),
        "dua_boarding_ship" to DuaText("船（乗り物）に乗る時", "アッラーの御名において、その航行も停泊もある。まことにわが主は赦す御方、慈悲深い御方です。", "船や乗り物に乗る時——ヌーフ預言者（彼に平安あれ）の言葉。", "クルアーンの一節——ヌーフ（彼に平安あれ）の箱舟のドゥアー。"),
        "dua_istighfar_hayyul_qayyum" to DuaText("ハイユル＝カイユームによる悔悟", "御方の他に神のない、永生にして維持者であるアッラーに御赦しを求め、御方に悔悟して立ち返ります。", "悔悟のために。", "たとえ戦場から逃げたとしても、彼の罪は赦される。"),
        "dua_rabbighfir_warham" to DuaText("わが主よ、赦し慈悲を", "わが主よ、赦し、御慈悲をお与えください。あなたは慈悲を示す者の中で最良の御方です。", "赦しと慈悲を求めるクルアーンのドゥアー。", "ムウミヌーン章の最後の一節。"),
        "dua_majlis_kaffarah" to DuaText("集いの贖罪", "おおアッラーよ、あなたに栄光あれ、あなたに称賛あれ。あなたの他に神はいないことを証言します。あなたに御赦しを求め、悔悟して立ち返ります。", "集いから立ち去る時に。", "その集いで語られた過ちに対する贖罪となる。"),
        "dua_jami_forgiveness" to DuaText("包括的な赦しのドゥアー", "おおアッラーよ、私の過ち、私の無知、私の事における行き過ぎ、そして私よりもあなたがよく御存知のすべてをお赦しください。", "預言者（彼に平安あれ）の包括的なドゥアー。", "預言者（彼に平安あれ）はよくこのドゥアーをされた。"),
        "dua_parents_nuh" to DuaText("ヌーフ（彼に平安あれ）の両親のためのドゥアー", "わが主よ、私と私の両親、そして信者として私の家に入るすべての者、そしてすべての信仰する男女をお赦しください。", "自らの両親と信者たちのために。", "ヌーフ預言者（彼に平安あれ）のドゥアー。"),
        "dua_shukr_parents" to DuaText("両親への感謝と正しい子孫", "わが主よ、あなたが私と私の両親に授けられた恩恵に感謝し、あなたが満足される正しい行いをなすことができますように。そして私の子孫を正しい者としてください。私はあなたに悔悟し、服従する者の一人です。", "四十歳に達した時のクルアーンのドゥアー。", "感謝、善行、そして子供たちの正しさ——すべてが一つのドゥアーに。"),
        "dua_intimacy" to DuaText("夫婦の交わりの前に", "アッラーの御名において。おおアッラーよ、悪魔を私たちから遠ざけ、あなたが私たちに授けられるもの（子供）から悪魔を遠ざけてください。", "夫婦の交わりの前に。", "もし子供が定められているなら、悪魔は決してその子に害を及ぼさない。"),
        "dua_ibrahim_children_protection" to DuaText("家と子供たちの守護", "わが主よ、この町を安全にし、私と私の子供たちを偶像崇拝から遠ざけてください。", "イブラーヒーム預言者（彼に平安あれ）のドゥアー——町と子供たちの安全のために。", "タウヒードに堅く留まるためのドゥアー。"),
        "dua_drinking_milk" to DuaText("牛乳を飲む時", "おおアッラーよ、私たちにそれを祝福し、さらに与えてください。", "牛乳を飲む時に。", "牛乳は食物としても飲み物としても十分である。"),
        "dua_iftar_host" to DuaText("誰かの家で断食を終える時", "断食する人々があなたのもとで断食を終え、正しい人々があなたの食物を食べ、天使たちがあなたのために祈りますように。", "誰かの家で断食を終える時に。", "もてなす人のための預言者（彼に平安あれ）のドゥアー。"),
        "dua_seeing_first_fruit" to DuaText("初物の果実を見た時", "おおアッラーよ、私たちの果実を祝福し、私たちの町を祝福し、私たちのサーウとムッド（計量単位）を祝福してください。", "季節の最初の果実を見た時に。", "糧と町の祝福のためのドゥアー。"),
        "dua_good_news" to DuaText("良い知らせを受けた時", "あらゆる称賛はアッラーに、御方の恩恵によって良いことが成就する。", "良い知らせを受けた時に（そして感謝の平伏を行う）。", "預言者（彼に平安あれ）は気に入ったことを見た時にこう仰せになった。"),
        "dua_looking_mirror" to DuaText("鏡を見る時", "おおアッラーよ、あなたが私の容姿を美しくされたように、私の人格も善くしてください。", "鏡を見る時に。", "預言者（彼に平安あれ）はこのドゥアーをされた（鏡に言及せずとも確立されている）。"),
        "dua_rabbana_taqabbal" to DuaText("行いの受け入れ", "わが主よ、私たちからこれをお受け入れください。まことにあなたは全聴にして全知であられます。そして私たちの悔悟をお受け入れください。まことにあなたは悔悟を受け入れる御方、慈悲深い御方です。", "イブラーヒームとイスマーイール（彼らに平安あれ）がカアバを建てる時に求めた。", "あらゆる善行の後にその受け入れを求めるドゥアー。"),
    )
}
